const fs = require('fs')
const path = require('path')

const {withXcodeProject} = require('expo/config-plugins')

/**
 * Copies the extension's Swift source out of `modules/` and into the generated
 * ios/ tree.
 *
 * `modules/` is the checked-in source of truth; ios/ is disposable and
 * regenerated by every `expo prebuild --clean`. Keeping the Swift outside ios/
 * is what makes the extension survive prebuild at all.
 */
const withExtensionSourceFiles = (config, {extensionName, controllerName}) => {
  return withXcodeProject(config, config => {
    const sourcePath = path.join(
      config.modRequest.projectRoot,
      'modules',
      extensionName,
      `${controllerName}.swift`,
    )
    const targetPath = path.join(
      config.modRequest.platformProjectRoot,
      extensionName,
      `${controllerName}.swift`,
    )

    fs.mkdirSync(path.dirname(targetPath), {recursive: true})
    fs.copyFileSync(sourcePath, targetPath)

    return config
  })
}

module.exports = {withExtensionSourceFiles}
